import java.util.*;
class RiverRoutingSeedTest{public static void main(String[]args){int n=96;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)h[z*n+x]=180-z*1.5f;var e=new EnvironmentMap(h);var a=RiverCourse.route(h,e,n,768,62,()->false,false,1,19753);var b=RiverCourse.route(h,e,n,768,62,()->false,false,1,19753);var c=RiverCourse.route(h,e,n,768,62,()->false,false,1,29871);if(!Arrays.equals(a.flow().parent(),b.flow().parent()))throw new AssertionError("River seed not deterministic");int changed=0;for(int i=0;i<h.length;i++)if(a.flow().parent()[i]!=c.flow().parent()[i])changed++;if(changed<100)throw new AssertionError("River seed does not replace routing: "+changed);System.out.println("PASS: repeatable seed; new seed changes "+changed+" drainage links without changing terrain");}}
